package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the new owner a deterministic {@code householdId} derived purely from its
 * {@code lastName} and {@code postcode}: the first twelve UPPER-case hex characters of
 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the id is a pure
 * function of those two fields, every owner with the same (normalized) last name and
 * postcode resolves to the same {@code householdId} automatically — they are, by
 * definition, the same household — regardless of registration order and independent of
 * the {@code sharesHousehold} create flag.
 *
 * <p>The flag no longer creates the household link; it only lets a second member of an
 * already-existing household bypass the duplicate block (see
 * {@link RejectDuplicateOwnerIdentity}). Everything that keys off the household —
 * duplicate detection and the household-size snapshot feeding the membership level —
 * reads this computed value.
 *
 * <p>No-ops (leaving {@code householdId} null, so the owner is a household of one) when
 * the owner has no last name or no postcode: without a postcode there is nothing to key
 * a household on.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        String lastName = normalize(owner.getLastName());
        String postcode = owner.getPostcode();
        if (lastName == null || postcode == null || postcode.isBlank()) {
            return; // no household without both a last name and a postcode
        }
        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
    }

    /** First twelve UPPER-case hex characters of SHA-256 over {@code lastName + '|' + postcode}. */
    private static String deriveHouseholdId(String lastName, String postcode) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", hash[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Last-name key: lower-cased, trimmed, with internal whitespace runs collapsed to one space. */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        return collapsed.isEmpty() ? null : collapsed.toLowerCase(Locale.ROOT);
    }
}
==== RejectDuplicateOwnerIdentity.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;

/**
 * The consolidated duplicate check, run after {@link AssignOwnerHousehold} (so the
 * deterministic {@code householdId} is set) and before {@link SaveOwner}. It rejects a
 * new owner as a 409 Conflict in two cases:
 *
 * <ul>
 * <li><b>Household duplicate</b> — the new owner's computed {@code householdId} matches an
 * existing owner's, i.e. it shares that owner's {@code lastName} and {@code postcode} and
 * is therefore the same household. Such a create is rejected <em>unless</em> it opted in
 * with {@code sharesHousehold}, in which case it is admitted as a declared additional
 * member of that household.</li>
 * <li><b>Exact identity duplicate</b> — the whole {@code identityKey} (see
 * {@link OwnerIdentity}) equals an existing owner's. This still applies to owners with no
 * household (no postcode), for whom the household rule cannot fire, and is never bypassed
 * by {@code sharesHousehold}: an identical owner is a hard duplicate, not a new member.</li>
 * </ul>
 *
 * <p>The {@code sharesHousehold} flag therefore no longer creates the household link (the
 * id is now derived purely from lastName+postcode); it only lets a genuine second member
 * through the duplicate block.
 */
public class RejectDuplicateOwnerIdentity {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerIdentityException {
        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
        String identityKey = OwnerIdentity.identityKey(owner);
        String householdId = owner.getHouseholdId();
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue; // never conflict with the owner itself
            }
            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
                throw new DuplicateOwnerIdentityException(
                        "An owner with the same identity already exists");
            }
            if (!sharesHousehold && householdId != null
                    && householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateOwnerIdentityException(
                        "An owner in the same household already exists");
            }
        }
    }
}

